 $("#incidentBody").addEventListener("click",e=>{const b=e.target.closest("[data-student-history]");if(!b)return;$("#studentHistoryPanel").dataset.studentId=b.dataset.studentHistory;renderStudentHistory();$("#studentHistoryPanel").scrollIntoView({behavior:"smooth",block:"start"});});$("#closeStudentHistory").addEventListener("click",()=>{$("#studentHistoryPanel").hidden=true;delete $("#studentHistoryPanel").dataset.studentId;});$("#printStudentHistory").addEventListener("click",()=>window.print());
 $("#journalForm").addEventListener("submit",saveJournalForm);$("#cancelJournalEdit").addEventListener("click",resetJournalForm);$("#journalSearch").addEventListener("input",renderJournal);$("#exportCalendarIcs").addEventListener("click",exportCalendar);$("#exportJournalCsv").addEventListener("click",exportJournalCsv);$("#journalTp").addEventListener("change",()=>{try{const t=JSON.parse($("#journalTp").value||"{}");if(t.subject)$("#journalSubject").value=t.subject;if(t.material)$("#journalMaterial").value=t.material;if(t.goal)$("#journalGoal").value=t.goal;}catch(e){}});$("#journalBody").addEventListener("click",e=>{const edit=e.target.closest("[data-edit-journal]");if(edit){editJournal(Number(edit.dataset.editJournal));return;}const del=e.target.closest("[data-delete-journal]");if(!del)return;const id=Number(del.dataset.deleteJournal),x=data.journals.find(r=>r.id===id);if(!x||!confirm("Hapus jurnal ini?"))return;data.journals=data.journals.filter(r=>r.id!==id);save();renderJournal();showToast("Jurnal dihapus.");});
 $("#backupAllData").addEventListener("click",exportAllBackup);$("#restoreAllData").addEventListener("click",()=>$("#restoreAllFile").click());$("#restoreAllFile").addEventListener("change",e=>{if(e.target.files&&e.target.files[0])restoreAllBackup(e.target.files[0]);});
  $("#gradeBody").addEventListener("change",e=>{
const input=e.target.closest("[data-grade-student]");if(!input)return;const studentId=Number(input.dataset.gradeStudent),subject=($("#subjectName").value||"Mata Pelajaran").trim();
if(input.value===""){data.gradeRecords=data.gradeRecords.filter(r=>!(r.studentId===studentId&&r.subject===subject));save();renderGrades();showToast("Nilai dikosongkan.");return;}
const raw=Number(input.value);if(!Number.isFinite(raw)||raw<0||raw>100){showToast("Nilai mentah harus 0 sampai 100.");renderGrades();return;}
let rec=data.gradeRecords.find(r=>r.studentId===studentId&&r.subject===subject);if(!rec){rec={studentId,subject,raw};data.gradeRecords.push(rec);}else rec.raw=raw;save();renderGrades();showToast("Nilai "+subject+" disimpan.");
});
